def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    # find horizontal rows: rows with >=2 cells of some color forming wide span
    def gapfill(row):
        from collections import defaultdict
        pos=defaultdict(list)
        for j,v in enumerate(row):
            if v: pos[v].append(j)
        for v,js in pos.items():
            if len(js)>=2:
                for j in range(min(js),max(js)+1):
                    if row[j]==0: row[j]=v
        return row
    hrows=set()
    for i,row in enumerate(out):
        before=row[:]
        gapfill(row)
        if any(v for v in row): hrows.add(i)
    # vertical sources: nonzero cells below the last horizontal row (from original)
    last_h=max(hrows)
    # paint upward helper
    def paint_up(r,c,v):
        r-=1
        while r>=0 and out[r][c]==0:
            out[r][c]=v; r-=1
    # gap marks: for each horizontal row, for each cell that was filled (col where orig 0 but now colored, in a horizontal row)
    for i in sorted(hrows):
        for j in range(w):
            if grid[i][j]==0 and out[i][j]!=0 and out[i][j]!=0:
                paint_up(i,j,out[i][j])
    # vertical lines below last horizontal row, top to bottom
    for i in range(last_h+1,h):
        for j in range(w):
            if out[i][j]!=0:
                paint_up(i,j,out[i][j])
    return out

