from collections import defaultdict

def color_runs(row):
    """Maximal runs of a color in a row, merging same-color runs separated by exactly one zero; [color, start, end]."""
    runs=[]; j=0; w=len(row)
    while j<w:
        if row[j]:
            k=j
            while k<w and row[k]==row[j]: k+=1
            runs.append([row[j],j,k-1]); j=k
        else: j+=1
