from collections import defaultdict

def fill_row_gaps(grid):
    """In each row, fill zero cells lying between two cells of the same color with that color."""
    out = [row[:] for row in grid]
    for row in out:
        pos = defaultdict(list)
        for j, v in enumerate(row):
            if v: pos[v].append(j)
        for v, js in pos.items():
            for j in range(min(js), max(js) + 1):
                if row[j] == 0: row[j] = v
    return out

def extend_up_marks(grid):
    """Fill row gaps, paint each filled gap column upward with its color, and vertical lines
    below the last horizontal row upward in their own color, stopping at any painted cell."""
    h, w = len(grid), len(grid[0])
    out = fill_row_gaps(grid)
    orig = [row[:] for row in grid]
    hrows = {i for i, row in enumerate(orig)
             if any(c >= 2 for c in defaultdict(int, {v: row.count(v) for v in set(row) if v}).values())}
    if not hrows: return out
    last_h = max(hrows)
    def paint_up(r, c, v):
        r -= 1
        while r >= 0 and out[r][c] == 0:
            out[r][c] = v; r -= 1
    for i in sorted(hrows):
        for j in range(w):
            if orig[i][j] == 0 and out[i][j] != 0:
                paint_up(i, j, out[i][j])
    for i in range(last_h + 1, h):
        for j in range(w):
            if out[i][j] != 0:
                paint_up(i, j, out[i][j])
    return out

